import { Router, Response, NextFunction } from 'express';
import { body } from 'express-validator';
import { Op } from 'sequelize';
import { User } from '../models/user.model';
import { UserController } from '../controllers/user.controller';
import { auth } from '../middlewares/auth.middleware';
import { validate } from '../middlewares/validate-request.middleware';
import { IAuthRequest } from '../interfaces/auth.interface';

const { auth: authenticateToken } = auth;

// Middleware kiểm tra quyền admin
const requireAdmin = (req: IAuthRequest, res: Response, next: NextFunction) => {
  if (req.user?.role === 'admin') {
    return next();
  }
  return res.status(403).json({
    success: false,
    message: 'Bạn không có quyền truy cập tài nguyên này',
  });
};


// Định nghĩa các hằng số cho validation messages
const VALIDATION_MESSAGES = {
  PASSWORD: {
    REQUIRED: 'Mật khẩu là bắt buộc',
    MIN_LENGTH: 'Mật khẩu phải có ít nhất 6 ký tự',
  },
  EMAIL: {
    VALID: 'Vui lòng nhập địa chỉ email hợp lệ',
    REQUIRED: 'Email là bắt buộc',
  },
  FULL_NAME: 'Họ và tên là bắt buộc',
  ROLE: 'Vai trò không hợp lệ',
  CURRENT_PASSWORD: 'Mật khẩu hiện tại là bắt buộc',
};

// Khởi tạo router
const router = Router();

// Middleware xác thực token cho tất cả các route
// Đảm bảo người dùng đã đăng nhập trước khi truy cập các route bên dưới
router.use(authenticateToken as any);

/**
 * @route GET /me
 * @desc Lấy thông tin người dùng hiện tại
 * @access Private - Yêu cầu đăng nhập
 */
router.get('/me', (req: IAuthRequest, res: Response, next: NextFunction) => {
  try {
    if (!req.user) {
      return res.status(401).json({
        success: false,
        message: 'Người dùng chưa đăng nhập',
      });
    }
    
    return res.status(200).json({
      success: true,
      data: req.user,
    });
  } catch (error) {
    next(error);
    return;
  }
});

/**
 * @route PATCH /change-password
 * @desc Đổi mật khẩu người dùng
 * @access Private - Yêu cầu đăng nhập
 */
router.patch(
  '/change-password',
  validate([
    body('currentPassword')
      .notEmpty()
      .withMessage(VALIDATION_MESSAGES.CURRENT_PASSWORD),
    body('newPassword')
      .isLength({ min: 6 })
      .withMessage(VALIDATION_MESSAGES.PASSWORD.MIN_LENGTH)
  ]),
  UserController.changePassword
);

// Middleware kiểm tra quyền admin cho các route bên dưới
// Chỉ admin mới có thể truy cập các route sau đây
router.use(requireAdmin);

/**
 * @route GET /
 * @desc Lấy danh sách người dùng (có phân trang và tìm kiếm)
 * @access Private - Chỉ admin
 * @query search - Từ khóa tìm kiếm (tùy chọn)
 */
router.get('/', async (req: IAuthRequest, res: Response, next: NextFunction) => {
  try {
    const searchTerm = req.query.search as string;
    const users = await User.findAll({
      attributes: { exclude: ['password'] },
      where: searchTerm ? {
        [Op.or]: [
          { email: { [Op.like]: `%${searchTerm}%` } },
          { full_name: { [Op.like]: `%${searchTerm}%` } },
        ],
      } : {},
    });
    
    return res.status(200).json({
      success: true,
      data: users,
    });
  } catch (error) {
    next(error);
    return; // Explicit return after next() to satisfy TypeScript
  }
});

/**
 * @route PATCH /:id/role
 * @desc Cập nhật vai trò của người dùng
 * @access Private - Chỉ admin
 * @param id - ID của người dùng cần cập nhật
 * @body role - Vai trò mới (admin/editor/user)
 */
router.patch(
  '/:id/role',
  validate([
    body('role')
      .isIn(['admin', 'editor', 'user'])
      .withMessage('Vai trò không hợp lệ. Vui lòng chọn một trong các vai trò: admin, editor, user')
  ]),
  UserController.updateUserRole
);

/**
 * @route PATCH /:id/status
 * @desc Kích hoạt hoặc vô hiệu hóa tài khoản người dùng
 * @access Private - Chỉ admin
 * @param id - ID của người dùng cần thay đổi trạng thái
 * @body is_active - Trạng thái mới (true/false)
 */
router.patch(
  '/:id/status',
  validate([
    body('is_active')
      .isBoolean()
      .withMessage('Trạng thái phải là true hoặc false')
  ]),
  UserController.toggleUserStatus
);

/**
 * @route DELETE /:id
 * @desc Xóa mềm tài khoản người dùng
 * @access Private - Chỉ admin
 * @param id - ID của người dùng cần xóa
 */
router.delete('/:id', UserController.deleteUser);

/**
 * @route GET /:id
 * @desc Lấy thông tin chi tiết của một người dùng
 * @access Private - Admin hoặc chính người dùng đó
 * @param id - ID của người dùng cần xem thông tin
 */
router.get('/:id', async (req: IAuthRequest, res: Response, next: NextFunction) => {
  try {
    if (!req.user) {
      return res.status(401).json({
        success: false,
        message: 'Chưa xác thực người dùng',
      });
    }

    // Nếu là admin hoặc là chính user đó
    if (req.user.role === 'admin' || req.user.id === req.params.id) {
      const user = await User.findByPk(req.params.id, {
        attributes: { exclude: ['password'] },
      });
      
      if (!user) {
        return res.status(404).json({
          success: false,
          message: 'Không tìm thấy người dùng',
        });
      }
      
      return res.status(200).json({
        success: true,
        data: user,
      });
    }
    
    return res.status(403).json({
      success: false,
      message: 'Bạn không có quyền xem thông tin người dùng này',
    });
  } catch (error) {
    next(error);
    return;
  }
});

/**
 * @route POST /
 * @desc Tạo mới một người dùng (chỉ admin)
 * @access Private - Chỉ admin
 * @body email - Email đăng nhập
 * @body password - Mật khẩu
 * @body full_name - Họ và tên
 * @body role - Vai trò (mặc định: user)
 */
router.post(
  '/',
  validate([
    body('email')
      .isEmail()
      .withMessage(VALIDATION_MESSAGES.EMAIL.VALID)
      .notEmpty()
      .withMessage(VALIDATION_MESSAGES.EMAIL.REQUIRED),
    body('password')
      .isLength({ min: 6 })
      .withMessage(VALIDATION_MESSAGES.PASSWORD.MIN_LENGTH)
      .notEmpty()
      .withMessage(VALIDATION_MESSAGES.PASSWORD.REQUIRED),
    body('fullName')
      .notEmpty()
      .withMessage(VALIDATION_MESSAGES.FULL_NAME),
    body('role')
      .isIn(['user', 'admin', 'moderator'])
      .withMessage(VALIDATION_MESSAGES.ROLE)
  ]),
  UserController.createUser
);

// Cập nhật thông tin người dùng (admin)
router.patch(
  '/:id',
  validate([
    body('email')
      .optional()
      .isEmail()
      .withMessage(VALIDATION_MESSAGES.EMAIL.VALID),
    body('fullName')
      .optional()
      .notEmpty()
      .withMessage(VALIDATION_MESSAGES.FULL_NAME),
    body('role')
      .optional()
      .isIn(['user', 'admin', 'moderator'])
      .withMessage(VALIDATION_MESSAGES.ROLE),
  ]),
  UserController.updateUser
);

// Xóa người dùng (admin)
router.delete('/:id', UserController.deleteUser);

export default router;
